using System;
using System.Linq;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Input;
using System.Windows.Media;
namespace LittleNotebook {public partial class MainWindow {
 Button miniPreviewEye;TextBlock miniClock;
 string FormatPuzzleTime(double seconds){var t=TimeSpan.FromSeconds(seconds);return ((int)t.TotalMinutes).ToString("00")+":"+t.Seconds.ToString("00")+"."+(t.Milliseconds/100);}
 string ExtraTitle(string key){return key=="crates"?T("Crate Garden","حديقة الصناديق"):key=="pour"?T("Colour Pour","قطرات الألوان"):T("Codebreaker","الرمز الخفي");}
 string ExtraInstructions(string key){return key=="crates"?T("Push every crate onto a leaf. Plan ahead: you can push, but cannot pull.","ادفع كل صندوق إلى ورقة. خطّط مسبقاً: يمكنك الدفع ولا يمكنك السحب."):key=="pour"?T("Pour into any glass with space. Sort each glass into one colour.","صب في أي أنبوب به مساحة. رتّب كل أنبوب بلون واحد."):T("Find the hidden code. Solid dots: exact; hollow dots: colour in another place.","اكتشف الرمز. الدائرة الممتلئة: مكان صحيح؛ الفارغة: لون في مكان آخر.");}
 string ExtraControls(string key){return key=="crates"?T("Arrow keys / W A S D or click a direction · U / Ctrl+Z to undo","الأسهم أو W A S D أو انقر باتجاه الحركة · U أو Ctrl+Z للتراجع"):key=="pour"?T("Choose a glass, then its destination · click again to deselect · U to undo","اختر أنبوباً ثم الوجهة · انقر مجدداً لإلغاء التحديد · U للتراجع"):T("Choose colours A–H or click · Enter checks your guess · U to undo","اختر الألوان بالحروف A–H أو بالنقر · Enter للتحقق · U للتراجع");}
 void UndoExtra(){if(mini==null||mini.Extra==null||mini.Phase=="complete")return;if(mini.Extra.Undo()){mini.Phase="playing";mini.Moves=mini.Extra.Moves;if(overlay.Children.Count>0)CloseModal();RefreshMiniHud();miniSurface.InvalidateVisual();FocusMiniSurface();}}
 void RefreshExtraHud(){var b=mini.Extra;miniLives.Text="";miniCounter.Text=b.Kind=="code"?b.Guesses.Count+" / "+b.Limit+T(" guesses"," محاولات"):b.Moves+T(" moves"," حركات");miniStatus.Text=mini.Phase=="complete"?T("Nicely done!  ","أحسنت! ")+FormatPuzzleTime(mini.Elapsed)+" · "+mini.Moves+T(" moves"," حركات"):b.Deadlocked?T("No winning moves remain. Restarting this level…","لا توجد حركات تؤدي للفوز. نعيد هذا المستوى…"):b.Message=="blocked"?T("That glass is full. Choose a glass with space.","هذا الأنبوب ممتلئ. اختر أنبوباً به مساحة."):b.Kind=="crates"?Enumerable.Range(0,b.Cells.Length).Count(i=>b.Goal[i]==1&&b.Cells[i]==1)+T(" crates on leaves"," صناديق على الأوراق"):b.Kind=="pour"?T("Select a glass, then pour into any glass with space.","اختر أنبوباً ثم صب في أي أنبوب به مساحة."):T("Colours may repeat. Feedback counts do not identify positions.","قد تتكرر الألوان. أعداد التلميحات لا تكشف مواضعها.");}
 bool ExtraKey(KeyEventArgs e){if(mini.Extra==null)return false;var b=mini.Extra;if(e.Key==Key.U||e.Key==Key.Z&&Keyboard.Modifiers==ModifierKeys.Control){if(!e.IsRepeat)UndoExtra();return true;}if(Keyboard.FocusedElement is Button)return false;int d=MiniDirection(e.Key);if(b.Kind=="crates"){if(d<0)return false;if(e.IsRepeat&&mini.Elapsed-extraLastKey<.11)return true;extraLastKey=mini.Elapsed;if(b.Move(d)){mini.CheckExtra();RefreshMiniHud();miniSurface.InvalidateVisual();}return true;}if(b.Kind=="code"){if(e.Key>=Key.A&&e.Key<=Key.H){MiniPress(100+e.Key-Key.A);return true;}if(e.Key==Key.Enter){MiniPress(99);return true;}}return false;}
 double extraLastKey=-1;
 void ShowMiniRecords(){string kind=Profile.Settings.SelectedMiniGame;Modal(MiniName(kind)+T(" · records"," · السجلات"),c=>{var list=new StackPanel{Width=590};if(kind=="stack")list.Children.Add(Text(T("High score: ","أعلى نتيجة: ")+Profile.StackBest,25,580));else if(kind=="mousedash")list.Children.Add(Text(T("Longest run: ","أطول محاولة: ")+FormatPuzzleTime(Profile.MiniGames[kind].BestSeconds),25,580));else {var record=Profile.MiniGames[kind];if(record.Results.Count==0)list.Children.Add(Text(T("Complete a puzzle to save its time and moves.","أكمل لغزاً لحفظ الوقت والحركات."),20,580));foreach(var result in record.Results.AsEnumerable().Reverse()){var row=Text(T("Level ","المستوى ")+result.Level+"   ·   "+FormatPuzzleTime(result.Seconds)+"   ·   "+result.Moves+T(" moves"," حركات"),19,580);row.Margin=new Thickness(6,8,6,8);list.Children.Add(row);}}var scroll=new ScrollViewer{Width=610,Height=345,Content=list,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};StylePaperScroll(scroll);Put(c,scroll,94,107);Btn(c,T("Close","إغلاق"),253,473,CloseModal,291,45);},560);}
 void ExtraFailure(){Modal(T("A fresh approach?","محاولة بطريقة أخرى؟"),c=>{Label(c,T("Your level is kept. Undo the last move, or restart this board.","يبقى مستواك محفوظاً. تراجع عن آخر حركة أو أعد اللوحة."),99,112,21,590);Btn(c,T("Undo last move","تراجع عن آخر حركة"),103,258,UndoExtra,280,48,true);Btn(c,T("Restart level","إعادة المستوى"),408,258,()=>StartMiniGame(mini.Kind),280,48);Btn(c,T("Back to minigames","العودة للألعاب المصغّرة"),215,326,BackToMiniGames,365,45);},420);}
 }
 public sealed partial class MiniGameBadge {
  static void DrawExtraBadge(DrawingContext dc,string kind,Palette p){Color c=MiniSurface.PuzzleColour(Array.IndexOf(ExtraPuzzle.Keys,kind));var brush=new SolidColorBrush(c);var pen=new Pen(new SolidColorBrush(p.Ink),1.4);dc.DrawRoundedRectangle(new SolidColorBrush(p.Paper),pen,new Rect(3,3,31,31),7,7);string mark=kind=="crates"?"▧":kind=="pour"?"◒":"✦";var text=new FormattedText(mark,System.Globalization.CultureInfo.InvariantCulture,FlowDirection.LeftToRight,new Typeface("Segoe UI Symbol"),25,brush,1);dc.DrawText(text,new Point(19-text.Width/2,18-text.Height/2));}
 }
 public sealed partial class MiniSurface {public static Color PuzzleColour(int index){return PuzzleColours[Math.Abs(index)%PuzzleColours.Length];}}
}
